Change this c++ code to python while keeping the functionality: 
"int main(void)
{
    int i;
    for (i=1; i<=100; i++)
    {
        // number divisible by 3 and 5 will
        // always be divisible by 15, print
        // 'FizzBuzz' in place of the number
        if (i%15 == 0)       
            printf ("FizzBuzz\t");   

        // number divisible by 3? print 'Fizz'
        // in place of the number
        else if ((i%3) == 0)   
            printf("Fizz\t");                

        // number divisible by 5, print 'Buzz' 
        // in place of the number
        else if ((i%5) == 0)                      
            printf("Buzz\t");                

        else // print the number           
            printf("%d\t", i);                

    }

    return 0;
}"

Make better, upgraded class Purtek for holding question answer data for training Keras Transformer model:

class Purtek:
    """ Single data representation for PurtkGPT """

    def __init__(self, question: str, answer: str, contex = '', kategoria = Kategoria.BRAK):
        # DATA
        self.question = question
        self.answer = answer
        self.contex = contex

        # INFO
        self.kategoria = kategoria

    def save(self, file_name):
        with open(file_name, 'w') as f:
            json.dump(self.__dict__, f)

    def load(self, file_name):
        with open(file_name, 'r') as f:
            self.__dict__.update(json.load(f))

    def __dict__(self):
        return {
            'question': self.question,
            'answer': self.answer,
            'contex': self.contex,
            'kategoria': self.kategoria
        }

